#include <stdio.h>
#include <time.h>

int main(void)
{
    struct tm sample = {0};
    char text[32];
    size_t written;

    sample.tm_year = 126; /* 2026 - 1900 */
    sample.tm_mon = 10;   /* November: 0-based */
    sample.tm_mday = 16;
    sample.tm_hour = 9;
    sample.tm_min = 30;
    sample.tm_sec = 0;

    written = strftime(text, sizeof text, "%Y-%m-%d %H:%M:%S", &sample);
    if (written == 0U) {
        puts("formatted text did not fit");
        return 1;
    }
    puts(text);
    return 0;
}

#include <stdio.h>
#include <time.h>

int main(void)
{
    time_t start = (time_t)1000;
    time_t finish = (time_t)4600;
    double elapsed = difftime(finish, start);

    printf("elapsed seconds: %.0f\n", elapsed);
    return 0;
}
